type dispatcherEventViewChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventViewChanged) Dispatch(e dpapp.EventViewChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventViewChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventViewChanged,
) error {
	if e.Tab == "" {
		return errors.New("EventViewChanged.Tab must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventViewChanged JSON: %w", err)
	}
	subj := "toxiproxy.view." + subject.Encode(string(e.Tab))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}

type dispatcherEventChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventChanged) Dispatch(e dpapp.EventChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventChanged,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventChanged JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjChanged, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjChanged, err)
	}
	return nil
}
